CREATE TABLE IF NOT EXISTS market_candles (instrument_id TEXT NOT NULL, timeframe TEXT NOT NULL, timestamp TIMESTAMPTZ NOT NULL, open NUMERIC NOT NULL, high NUMERIC NOT NULL, low NUMERIC NOT NULL, close NUMERIC NOT NULL, volume NUMERIC NOT NULL, quality_state TEXT NOT NULL, PRIMARY KEY (instrument_id, timeframe, timestamp));
CREATE TABLE IF NOT EXISTS option_snapshots (instrument_id TEXT NOT NULL, timestamp TIMESTAMPTZ NOT NULL, ltp NUMERIC, oi NUMERIC, oi_change NUMERIC, iv NUMERIC, volume NUMERIC, bid NUMERIC, ask NUMERIC, quality_state TEXT NOT NULL, PRIMARY KEY (instrument_id, timestamp));
CREATE TABLE IF NOT EXISTS news_outcomes (event_id TEXT NOT NULL, horizon TEXT NOT NULL, realized_move NUMERIC, evaluated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (event_id, horizon));